/**
 * The control-plane HTTP server (§8).
 *
 *  - `node:http`, no framework;
 *  - `/healthz` at the root, everything else under `/api/v1`;
 *  - an `X-Request-Id` on every response, generated by the server;
 *  - the migration runner runs BEFORE the listener binds (§9.4);
 *  - errors are generic on the wire and detailed only in the log (§8.2);
 *  - in production the same origin serves `frontend/dist` (§8.1), so there is
 *    no proxy hop and the same-origin rule still holds.
 */

import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { createServer as createHttpServer, type IncomingMessage, type Server, type ServerResponse } from 'node:http';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import type { HealthResponse } from './contracts/api.ts';
import type { SandboxProvider } from './contracts/sandbox.ts';
import { ConfigError, parseConfig, type Config } from './config.ts';
import { currentSchemaVersion, migrate } from './db/migrate.ts';
import { closeDatabase, openDatabase, type Database } from './db/sqlite.ts';
import { createStores } from './db/store/index.ts';
import { ApiError, statusFor, toErrorBody } from './http/errors.ts';
import { sendJson } from './http/json.ts';
import { Router } from './http/router.ts';
import { createLiveClient } from './inference/client.ts';
import { createMockClient } from './inference/mock.ts';
import type { InferenceClient } from './inference/types.ts';
import { logger, type Logger } from './log.ts';
import { RunManager } from './runs/manager.ts';
import { createStandinProvider } from './runs/standinProvider.ts';
import { registerFixtureRoutes } from './routes/fixtures.ts';
import { registerRunRoutes } from './routes/runs.ts';
import { registerWorkloadRoutes } from './routes/workloads.ts';

/**
 * A URL parser base. It is deliberately not an http(s) origin: the server
 * never needs an absolute URL, and no host may be hardcoded (§10.8, C1).
 */
const INTERNAL_URL_BASE = 'brz://control-plane';

const DIST_ROOT = fileURLToPath(new URL('../../frontend/dist/', import.meta.url));

export interface StartServerOptions {
  readonly config: Config;
  readonly provider: SandboxProvider;
  /** Injected by tests; the default is built from `config.inference`. */
  readonly createInference?: () => InferenceClient;
  readonly log?: Logger;
}

export interface RunningServer {
  readonly server: Server;
  readonly manager: RunManager;
  readonly port: number;
  readonly address: string;
  close(): Promise<void>;
}

/**
 * The sealed tiers are brief 06. This build refuses to pretend they exist: the
 * only provider it can hand out is the non-sealed stand-in.
 */
export function createProvider(kind: SandboxProvider['kind']): SandboxProvider {
  if (kind === 'standin') return createStandinProvider();
  throw new ConfigError(
    `The ${kind} sandbox provider is not available in this build: the sealed tiers land in brief 06.`,
  );
}

function createInferenceFactory(config: Config): () => InferenceClient {
  if (config.inference.mode === 'mock') {
    // A fresh transcript cursor per run: the mock is deterministic per run.
    return () => createMockClient();
  }
  const { endpoint, model, apiKey } = config.inference;
  if (endpoint === null || model === null || apiKey === null) {
    throw new ConfigError(
      'Live inference requires OPENAI_ENDPOINT, OPENAI_MODEL and OPENAI_API_KEY. The values are never printed.',
    );
  }
  return () =>
    createLiveClient({
      endpoint,
      model,
      apiKey,
      timeoutMs: config.inference.timeoutMs,
      maxRetries: config.inference.maxRetries,
      logger,
    });
}

function readVersion(): string {
  try {
    const raw = readFileSync(new URL('../package.json', import.meta.url), 'utf8');
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed === 'object' && parsed !== null) {
      const version = (parsed as Record<string, unknown>)['version'];
      if (typeof version === 'string' && version.length > 0) return version;
    }
  } catch {
    // A missing or unreadable manifest is not a reason to fail health.
  }
  return 'unknown';
}

function databaseState(db: Database): { state: HealthResponse['database']['state']; schemaVersion: number | null } {
  try {
    const schemaVersion = currentSchemaVersion(db);
    return { state: schemaVersion === null ? 'not-migrated' : 'ready', schemaVersion };
  } catch {
    return { state: 'error', schemaVersion: null };
  }
}

const CONTENT_TYPES: Readonly<Record<string, string>> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.ico': 'image/x-icon',
  '.woff2': 'font/woff2',
  '.map': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
};

function isInside(root: string, candidate: string): boolean {
  const relative = path.relative(root, candidate);
  return relative.length === 0 || (!relative.startsWith('..') && !path.isAbsolute(relative));
}

/**
 * Serve the built frontend when it exists. A missing `frontend/dist` is not an
 * error: in development Vite serves the app and proxies `/api` (§10.6).
 */
async function serveStatic(res: ServerResponse, pathname: string, requestId: string): Promise<boolean> {
  if (!existsSync(DIST_ROOT)) return false;

  let decoded: string;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    return false;
  }

  const requested = path.resolve(DIST_ROOT, `.${decoded}`);
  const candidate = isInside(DIST_ROOT, requested) && existsSync(requested) && path.extname(requested) !== ''
    ? requested
    : path.join(DIST_ROOT, 'index.html');

  if (!isInside(DIST_ROOT, candidate) || !existsSync(candidate)) return false;

  try {
    const body = await readFile(candidate);
    res.statusCode = 200;
    res.setHeader('content-type', CONTENT_TYPES[path.extname(candidate).toLowerCase()] ?? 'application/octet-stream');
    res.setHeader('x-request-id', requestId);
    res.end(body);
    return true;
  } catch {
    return false;
  }
}

interface HandlerDeps {
  readonly config: Config;
  readonly db: Database;
  readonly provider: SandboxProvider;
  readonly router: Router;
  readonly startedAt: number;
  readonly version: string;
}

function createRequestHandler(deps: HandlerDeps): (req: IncomingMessage, res: ServerResponse) => void {
  const { config, db, provider, router, startedAt, version } = deps;

  return (req, res) => {
    const requestId = `req_${randomBytes(8).toString('hex')}`;
    res.setHeader('x-request-id', requestId);

    void (async () => {
      let url: URL;
      try {
        url = new URL(req.url ?? '/', INTERNAL_URL_BASE);
      } catch {
        throw new ApiError('invalid_request', [{ field: 'url', issue: 'The URL is not valid.' }]);
      }

      if (url.pathname === '/healthz') {
        const database = databaseState(db);
        const body: HealthResponse = {
          status: database.state === 'ready' ? 'ok' : 'degraded',
          version,
          inferenceMode: config.inference.mode,
          database,
          provider: provider.kind,
          cgroupV2: provider.supports.cgroupV2,
          uptimeSeconds: Math.max(0, Math.floor((Date.now() - startedAt) / 1000)),
        };
        sendJson(res, 200, body, requestId);
        return;
      }

      const match = router.match(req.method ?? 'GET', url.pathname);
      if (match === null) {
        if (url.pathname.startsWith('/api/')) throw new ApiError('not_found');
        if (req.method === 'GET' && (await serveStatic(res, url.pathname, requestId))) return;
        throw new ApiError('not_found');
      }

      await match.handler({
        req,
        res,
        url,
        params: match.params,
        requestId,
      });
    })().catch((error: unknown) => {
      const status = statusFor(error);
      if (!(error instanceof ApiError)) {
        logger.error('unhandled request error', error, { requestId, method: req.method ?? '', path: req.url ?? '' });
      }
      if (res.headersSent) {
        res.destroy();
        return;
      }
      sendJson(res, status, toErrorBody(error, requestId), requestId);
    });
  };
}

function listen(server: Server, port: number, host: string): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const onError = (error: Error): void => {
      server.removeListener('listening', onListening);
      reject(error);
    };
    const onListening = (): void => {
      server.removeListener('error', onError);
      resolve();
    };
    server.once('error', onError);
    server.once('listening', onListening);
    server.listen(port, host);
  });
}

/** Open + migrate + wire + listen. Throws before binding if anything fails. */
export async function startServer(options: StartServerOptions): Promise<RunningServer> {
  const { config } = options;
  const log = options.log ?? logger;
  const provider = options.provider;
  const createInference = options.createInference ?? createInferenceFactory(config);

  const db = openDatabase(config.dbPath);
  try {
    const result = migrate(db);
    log.info('schema ready', {
      schemaVersion: result.schemaVersion,
      applied: result.applied,
    });
  } catch (error) {
    closeDatabase(db);
    throw error;
  }

  const stores = createStores(db);
  const manager = new RunManager({
    config,
    stores,
    provider,
    createInference,
    logger: log,
  });
  manager.recoverOrphans();

  const router = new Router();
  registerWorkloadRoutes(router);
  registerFixtureRoutes(router);
  registerRunRoutes(router, { config, stores, manager });

  const startedAt = Date.now();
  const server = createHttpServer(
    createRequestHandler({
      config,
      db,
      provider,
      router,
      startedAt,
      version: readVersion(),
    }),
  );

  await listen(server, config.port, config.host);
  const addressInfo = server.address();
  const port = typeof addressInfo === 'object' && addressInfo !== null ? addressInfo.port : config.port;
  const address = typeof addressInfo === 'object' && addressInfo !== null ? addressInfo.address : config.host;

  let closing: Promise<void> | null = null;
  const close = (): Promise<void> => {
    if (closing !== null) return closing;
    closing = (async () => {
      // Abort and drain every live run first: their `finally` blocks write the
      // teardown record and the report before the database closes.
      await manager.shutdown();
      await new Promise<void>((resolve) => {
        server.close(() => resolve());
        server.closeIdleConnections();
      });
      closeDatabase(db);
    })();
    return closing;
  };

  return { server, manager, port, address, close };
}

async function main(): Promise<void> {
  const config = parseConfig();
  const provider = createProvider(config.sandboxProvider);
  const running = await startServer({ config, provider });

  logger.info('control plane listening', {
    host: config.host,
    port: running.port,
    inferenceMode: config.inference.mode,
    provider: config.sandboxProvider,
  });

  const shutdown = (signal: string): void => {
    logger.info('shutdown requested', { signal });
    void running
      .close()
      .then(() => {
        process.exit(0);
      })
      .catch((error: unknown) => {
        logger.error('shutdown failed', error);
        process.exit(1);
      });
  };

  process.once('SIGINT', () => shutdown('SIGINT'));
  process.once('SIGTERM', () => shutdown('SIGTERM'));
}

const invokedDirectly =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;

if (invokedDirectly) {
  main().catch((error: unknown) => {
    if (error instanceof ConfigError) {
      // The message names the variable, never the value (§10.8).
      logger.error('configuration error', error);
    } else {
      logger.error('startup failed', error);
    }
    process.exitCode = 1;
  });
}
